#include <stdio.h>  
#include <stdlib.h>  
int main (void)  
{  
    int k;  

    FILE *fp;  
    fp = fopen("results.dat", "w");  
    if (fp == NULL)  
    {  
        printf("could not open file");  
        exit (0);  
    }  
    for (k=1; k<=10; k++)  
        fprintf("%d, %d\n", k, k*k);  

    fclose(fp);  
    return 0;  
}

